                    seen.add((nr, nx))
                    stack.append((nr, nx))
        markers[color] = count

    rods = {}
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 0:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != 0:
                r += 1
            end = r - 1
            if end - start < 2:
                continue
            cap = grid[start][c]
            body = {grid[y][c] for y in range(start + 1, end)}
            if grid[end][c] == cap and len(body) == 1 and cap not in body:
